import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {readFileSync,writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
const path=name=>fileURLToPath(new URL(name,import.meta.url));
const variant=process.argv[2];
for(const driver of ['deepbench','lookupbench']){
 const record=/function _M0TP210JingLan0v03stn13ScheduledTask\([^\n]*\) \{/;
 let source=readFileSync(path(variant+'-'+driver+'.js'),'utf8');
 assert(record.test(source));
 source=source.replace(record,'$&\n  stats.records++;');
 const root='_M0FP210JingLan0v03stn25first__resource__conflict';
 const linked='_M0FP210JingLan0v03stn23first__linked__conflict';
 const schedule='_M0FP210JingLan0v03stn22schedule__from__values';
 const symbols={root,linked};
 if(variant==='base'){
  const begin=/^( +)let schedule;$/m;
  const end=/^( +)let conflict;$/m;
  assert(begin.test(source)&&end.test(source));
  source=source.replace(begin,'$1const scheduleStarted = performance.now();\n$&')
   .replace(end,'$1stats.calls.schedule++; stats.ms.schedule += performance.now() - scheduleStarted;\n$&');
 }else if(variant!=='inline'){symbols.schedule=schedule;}
 const timers=Object.entries(symbols).map(([field,name])=>{
  assert(source.includes('function '+name+'('));
  return `const saved_${field} = ${name};
${name} = (...args) => {
 stats.calls.${field}++;
 const started = performance.now();
 try { return saved_${field}(...args); }
 finally { stats.ms.${field} += performance.now() - started; }
};`;
 });
 const header=`const stats={records:0,calls:{root:0,linked:0,schedule:0},ms:{root:0,linked:0,schedule:0}};
${timers.join('\n')}
process.once('exit',()=>console.error(JSON.stringify(stats)));\n`;
 writeFileSync(path(variant+'-'+driver+'-probe.js'),header+source);
}
const rows=[];
for(const name of ['tight-impossible','maintenance','independent','distinct-resources','four-resources','max-model','max-root']){
 const args=name==='tight-impossible'?[path(variant+'-deepbench-probe.js')]:[path(variant+'-lookupbench-probe.js'),name];
 const samples=Array.from({length:3},()=>{
  const p=spawnSync(process.execPath,args,{encoding:'utf8',timeout:40000});
  assert.equal(p.status,0,p.stderr);
  assert.equal(p.stdout.trim().split(/\r?\n/).length,9);
  return JSON.parse(p.stderr);
 });
 rows.push({name,samples});
 console.log(name,JSON.stringify(samples[0]));
}
writeFileSync(path(variant+'-probe.json'),JSON.stringify(rows,null,2)+'\n');

